from pathlib import Path
from typing import Any, Dict, List, Optional
from fastapi import HTTPException, status

from app.config import DISCLAIMER_TEXT, SAVED_MODELS_DIR, WORKSPACE_DIR
from app.tasks.base import BaseMriTask, TaskInfo, TaskSetupGuide, TaskStatus

class StrokeTask(BaseMriTask):
    """
    Modular task for Stroke-Related MRI Classification & Infarct Assessment.
    Currently in setup state: requires calibrated DWI/ADC/FLAIR imaging data
    and trained model checkpoint.
    """

    task_id = "stroke"
    name = "Stroke-Related MRI Classification"
    short_title = "Stroke Assessment"
    category = "Cerebrovascular Disease"
    tagline = "Diffusion-Weighted (DWI) & ADC map evaluation for acute ischemic and hemorrhagic patterns"
    description = (
        "Designed to investigate deep learning pipelines for identifying acute cerebral ischemia "
        "versus hemorrhagic transformation. Highlights the critical role of biophysical diffusion parameters "
        "(restricted diffusion on DWI matched with ADC hypointensity) in acute stroke evaluation."
    )
    supported_scan_types = ["MRI"]
    required_sequences = [
        "Diffusion-Weighted Imaging (DWI b=1000)",
        "Apparent Diffusion Coefficient (ADC) Map",
        "T2-FLAIR",
    ]
    supported_orientations = ["Axial"]
    supported_formats = [".jpg", ".jpeg", ".png"]
    limitations = [
        "Dataset & Model Setup Required: This task is currently unconfigured. No inference allowed.",
        "Acute stroke is a time-critical medical emergency ('time is brain'). AI models are for research exploration only.",
        "DWI 'shine-through' artifacts on T2 images mimic acute infarction without true restricted diffusion.",
        "Uncalibrated 8-bit JPEG images discard quantitative ADC diffusion coefficients ($mm^2/s$).",
    ]
    disclaimer = DISCLAIMER_TEXT

    def __init__(self):
        self.model_path = SAVED_MODELS_DIR / "axonova_stroke_best.keras"
        self.dataset_dir = WORKSPACE_DIR / "dataset" / "stroke"

    def is_ready(self) -> bool:
        return self.model_path.exists() and self.dataset_dir.exists()

    def get_status(self) -> TaskStatus:
        return "ready" if self.is_ready() else "setup_required"

    def get_class_labels(self) -> List[str]:
        return []

    def get_setup_guide(self) -> TaskSetupGuide:
        return TaskSetupGuide(
            recommended_datasets=[
                "ISLES (Ischemic Stroke Lesion Segmentation Challenge) - isles-challenge.org",
                "ATLAS (Anatomical Tracings of Lesions After Stroke) Open Database",
                "PhysioNet / PhysioZoo Stroke MRI Archives",
            ],
            required_sequences=["DWI (b=1000 s/mm²)", "ADC Map", "T2-FLAIR (to assess DWI-FLAIR mismatch)"],
            split_policy=(
                "STRICT SCAN & SUBJECT-LEVEL SPLIT: Patient scans must never be separated across slices into "
                "both train and test splits. Onset timestamp stratifications should also avoid leakage between "
                "hyperacute (<4.5h), acute, and subacute patient presentations."
            ),
            target_classes=[
                "Acute Ischemic Infarction",
                "Subacute / Chronic Infarct",
                "Intracerebral Hemorrhage",
                "No Acute Infarction",
            ],
            expected_model_path=str(self.model_path),
            expected_dataset_dir=str(self.dataset_dir),
            data_leakage_risks=[
                "Multi-slice volume leakage from single acute ischemic episode.",
                "DWI/ADC pairing mismatches causing erroneous hyperintensity interpretation.",
                "Scanner gradient calibration discrepancies across hospital centers.",
            ],
            setup_steps=[
                "1. Download curated stroke cohort (e.g. ISLES 2022 / ATLAS v2.0).",
                "2. Standardize DWI and co-registered ADC maps.",
                "3. Organize scans in dataset/stroke/{train,val,test}/ with subject-level splits.",
                "4. Train task-specific network: python -m model.train_stroke.",
                "5. Save weights to backend/saved_models/axonova_stroke_best.keras.",
            ],
        )

    def get_task_info(self) -> TaskInfo:
        return TaskInfo(
            task_id=self.task_id,
            name=self.name,
            short_title=self.short_title,
            category=self.category,
            status=self.get_status(),
            tagline=self.tagline,
            description=self.description,
            supported_scan_types=self.supported_scan_types,
            required_sequences=self.required_sequences,
            supported_orientations=self.supported_orientations,
            supported_formats=self.supported_formats,
            class_labels=self.get_class_labels(),
            model_loaded=self.is_ready(),
            model_name=None,
            model_version=None,
            input_shape=None,
            trainable_parameters=None,
            evaluation_available=False,
            overall_accuracy=None,
            limitations=self.limitations,
            disclaimer=self.disclaimer,
            setup_guide=self.get_setup_guide(),
        )

    def get_model_info(self) -> Dict[str, Any]:
        return {
            "loaded": False,
            "task_id": self.task_id,
            "model_name": None,
            "training_status": "Dataset/model setup required",
            "supported_classes": [],
            "supported_scan_type": "MRI",
            "evaluation_available": False,
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def get_evaluation(self) -> Dict[str, Any]:
        return {
            "evaluated": False,
            "task_id": self.task_id,
            "reason": "Model weights and evaluation results not configured yet.",
            "disclaimer": self.disclaimer,
        }

    def get_dataset_info(self) -> Dict[str, Any]:
        return {
            "available": False,
            "task_id": self.task_id,
            "dataset_name": "Stroke MRI Research Dataset",
            "source": "ISLES / ATLAS (Pending Setup)",
            "total_images": 0,
            "class_distribution": {},
            "split_counts": {},
            "disclaimer": self.disclaimer,
            "setup_guide": self.get_setup_guide().model_dump(),
        }

    def predict(
        self,
        file_bytes: bytes,
        scan_type: str,
        orientation: str,
        filename: str = "uploaded_scan.jpg",
    ) -> Dict[str, Any]:
        raise HTTPException(
            status_code=status.HTTP_400_BAD_REQUEST,
            detail=(
                "Task 'Stroke-Related MRI Classification' is not enabled. "
                "DWI/ADC dataset and trained model checkpoint are required. "
                "Simulated or placeholder predictions are strictly prohibited."
            ),
        )
